'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  useReducedMotion,
} from 'motion/react';
import { useState } from 'react';

import { type NavLink } from './data';

const HIGHLIGHT_TRANSITION: Transition = {
  type: 'spring',
  bounce: 0,
  duration: 0.3,
};

const INSTANT_LAYOUT: Transition = {
  layout: { duration: 0 },
  opacity: { duration: 0.15 },
};

function highlightTransitionOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return INSTANT_LAYOUT;
  }
  return HIGHLIGHT_TRANSITION;
}

function currentAttributeOf(isCurrent: boolean) {
  if (isCurrent) {
    return 'page' as const;
  }
  return undefined;
}

type NavLinksProps = {
  links: NavLink[];
  currentId: string | null;
};

export function NavLinks({ links, currentId }: NavLinksProps) {
  const [hoveredId, setHoveredId] = useState<string | null>(null);
  const shouldReduceMotion = useReducedMotion();
  const highlightTransition = highlightTransitionOf(shouldReduceMotion);

  function clearHover() {
    setHoveredId(null);
  }

  return (
    <nav aria-label='Main' className='hidden md:block'>
      <ul className='flex items-center' onPointerLeave={clearHover}>
        {links.map((link) => {
          const isHovered = hoveredId === link.id;
          const isCurrent = currentId === link.id;

          function highlight() {
            setHoveredId(link.id);
          }

          return (
            <li key={link.id}>
              <a
                href={link.href}
                aria-current={currentAttributeOf(isCurrent)}
                onPointerEnter={highlight}
                onFocus={highlight}
                onBlur={clearHover}
                className='text-muted-foreground hover:text-foreground aria-[current=page]:text-foreground focus-visible:ring-ring/25 relative inline-flex h-8 items-center rounded-full px-3 text-[13px] font-medium transition-colors outline-none focus-visible:ring-[3px]'
              >
                <AnimatePresence>
                  {isHovered && (
                    <motion.span
                      layoutId='marketing-05-nav-highlight'
                      aria-hidden='true'
                      className='bg-foreground/5 absolute inset-0 rounded-full'
                      initial={{ opacity: 0 }}
                      animate={{ opacity: 1 }}
                      exit={{ opacity: 0 }}
                      transition={highlightTransition}
                    />
                  )}
                </AnimatePresence>
                <span className='relative'>{link.label}</span>
              </a>
            </li>
          );
        })}
      </ul>
    </nav>
  );
}

'use client';

import { useRef, useState } from 'react';

import { MenuIcon } from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';
import { SelectedMark } from '@/registry/ndeko/ui/selected-mark';
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetFooter,
  SheetHeader,
  SheetTitle,
  SheetTrigger,
} from '@/registry/ndeko/ui/sheet';

import { DriftdeskMark } from './brand-mark';
import { HEADER, type NavLink } from './data';
import { scrollToSection, sectionHashOf } from './section-link';

function currentAttributeOf(isCurrent: boolean) {
  if (isCurrent) {
    return 'page' as const;
  }
  return undefined;
}

type MobileSheetProps = {
  links: NavLink[];
  currentId: string | null;
};

export function MobileSheet({ links, currentId }: MobileSheetProps) {
  const [isOpen, setIsOpen] = useState(false);
  const [shouldReturnFocus, setShouldReturnFocus] = useState(true);
  const pendingHashRef = useRef<string | null>(null);

  function changeOpen(open: boolean) {
    if (open) {
      setShouldReturnFocus(true);
    }
    setIsOpen(open);
  }

  function followLink(event: React.MouseEvent<HTMLElement>) {
    const href = event.currentTarget.getAttribute('href');
    const sectionHash = sectionHashOf(href);
    setShouldReturnFocus(false);
    setIsOpen(false);
    if (sectionHash === null) {
      return;
    }
    event.preventDefault();
    pendingHashRef.current = sectionHash;
  }

  function finishOpenChange(open: boolean) {
    const pendingHash = pendingHashRef.current;
    pendingHashRef.current = null;
    if (open) {
      return;
    }
    if (pendingHash === null) {
      return;
    }
    scrollToSection(pendingHash);
  }

  return (
    <Sheet
      open={isOpen}
      onOpenChange={changeOpen}
      onOpenChangeComplete={finishOpenChange}
    >
      <SheetTrigger
        render={
          <Button
            variant='ghost'
            size='icon'
            className='md:hidden'
            aria-label='Open menu'
          />
        }
      >
        <MenuIcon />
      </SheetTrigger>
      <SheetContent side='right' finalFocus={shouldReturnFocus}>
        <SheetHeader>
          <SheetTitle className='flex items-center gap-2'>
            <DriftdeskMark />
            Driftdesk
          </SheetTitle>
          <SheetDescription>{HEADER.tagline}</SheetDescription>
        </SheetHeader>
        <nav aria-label='Main'>
          <ul className='flex flex-col gap-0.5'>
            {links.map((link) => {
              const isCurrent = currentId === link.id;

              return (
                <li key={link.id}>
                  <a
                    href={link.href}
                    aria-current={currentAttributeOf(isCurrent)}
                    onClick={followLink}
                    className='text-foreground hover:bg-foreground/5 aria-[current=page]:bg-foreground/5 focus-visible:ring-ring/25 flex h-11 items-center justify-between rounded-md px-3 text-base font-medium transition-colors outline-none focus-visible:ring-[3px]'
                  >
                    {link.label}
                    {isCurrent && <SelectedMark />}
                  </a>
                </li>
              );
            })}
          </ul>
        </nav>
        <SheetFooter>
          <Button
            variant='outline'
            size='lg'
            nativeButton={false}
            render={<a href='#' />}
          >
            Sign in
          </Button>
          <Button
            size='lg'
            nativeButton={false}
            render={<a href={HEADER.actionHref} />}
            onClick={followLink}
          >
            {HEADER.action}
          </Button>
        </SheetFooter>
      </SheetContent>
    </Sheet>
  );
}

const SECTION_HASH_PATTERN = /^#.+/;

export function sectionHashOf(href: string | null) {
  if (href === null) {
    return null;
  }
  const isSectionHash = SECTION_HASH_PATTERN.test(href);
  if (!isSectionHash) {
    return null;
  }
  return href;
}

export function scrollToSection(hash: string) {
  const id = hash.slice(1);
  const target = document.getElementById(id);
  target?.scrollIntoView();
}

import { ContactForm } from './contact-form';
import { CONTACT, CONTACT_ANCHOR, CONTACT_DETAILS } from './data';

export function Contact() {
  return (
    <section
      id={CONTACT_ANCHOR}
      className='px-4 py-16 sm:px-6 sm:py-24 lg:px-8'
    >
      <div className='mx-auto grid max-w-6xl gap-10 lg:grid-cols-[minmax(0,2fr)_minmax(0,3fr)] lg:gap-16'>
        <div className='flex flex-col gap-8'>
          <div className='flex flex-col gap-3'>
            <h1 className='text-2xl font-semibold text-balance sm:text-3xl'>
              {CONTACT.title}
            </h1>
            <p className='text-muted-foreground max-w-md text-base text-pretty'>
              {CONTACT.description}
            </p>
          </div>
          <dl className='flex flex-col gap-4'>
            {CONTACT_DETAILS.map((detail) => (
              <div key={detail.label} className='flex items-center gap-3'>
                <span className='keycap-3d text-muted-foreground flex size-8 shrink-0 items-center justify-center rounded-lg'>
                  <detail.icon />
                </span>
                <div className='flex min-w-0 flex-col'>
                  <dt className='text-muted-foreground text-xs'>
                    {detail.label}
                  </dt>
                  <dd className='text-[13px] font-medium'>
                    {detail.href && (
                      <a
                        href={detail.href}
                        className='text-primary-ink focus-visible:ring-ring/25 rounded-sm underline-offset-4 outline-none hover:underline focus-visible:ring-[3px]'
                      >
                        {detail.value}
                      </a>
                    )}
                    {!detail.href && detail.value}
                  </dd>
                </div>
              </div>
            ))}
          </dl>
        </div>
        <ContactForm />
      </div>
    </section>
  );
}

'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
  useReducedMotion,
} from 'motion/react';
import { useEffect, useId, useRef, useState } from 'react';

import { LoaderCircleIcon, SendIcon } from '@/registry/ndeko/lib/icons';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button } from '@/registry/ndeko/ui/button';
import {
  Field,
  FieldDescription,
  FieldError,
  FieldLabel,
} from '@/registry/ndeko/ui/field';
import { Input } from '@/registry/ndeko/ui/input';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/registry/ndeko/ui/select';
import { StatusOrb } from '@/registry/ndeko/ui/status-orb';
import { Textarea } from '@/registry/ndeko/ui/textarea';

import { TEAM_SIZES } from './data';
import {
  type ContactErrors,
  type ContactField,
  EMPTY_VALUES,
  errorsOf,
  firstInvalidFieldOf,
  firstNameOf,
  isContactField,
  MESSAGE_MAX_LENGTH,
} from './validation';

type Status = 'editing' | 'sending' | 'sent';

const SEND_DELAY_MS = 1200;

const MESSAGE_COUNT_FORMAT = new Intl.NumberFormat('en');

const PANEL_TRANSITION: Transition = {
  duration: 0.2,
  ease: [0.23, 1, 0.32, 1],
};

const LABEL_TRANSITION: Transition = {
  type: 'spring',
  bounce: 0,
  duration: 0.3,
};

const INSTANT: Transition = { duration: 0 };

const PANEL_VARIANTS: Variants = {
  enter: { opacity: 0, scale: 0.98, filter: 'blur(2px)' },
  visible: { opacity: 1, scale: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, scale: 0.98, filter: 'blur(2px)' },
};

const ICON_VARIANTS: Variants = {
  enter: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  visible: { opacity: 1, scale: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
};

const FADE_VARIANTS: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1 },
  exit: { opacity: 0 },
};

function panelVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return PANEL_VARIANTS;
}

function iconVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return ICON_VARIANTS;
}

function labelTransitionOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return INSTANT;
  }
  return LABEL_TRANSITION;
}

function sendLabelOf(isSending: boolean) {
  if (isSending) {
    return 'Sending';
  }
  return 'Send message';
}

function sendGlyphOf(isSending: boolean) {
  if (isSending) {
    return {
      key: 'sending',
      icon: <LoaderCircleIcon className='animate-spin' />,
    };
  }
  return { key: 'send', icon: <SendIcon /> };
}

function selectedValueOf(value: string) {
  if (value.length === 0) {
    return null;
  }
  return value;
}

function describedByOf(hintId: string, errorId: string, hasError: boolean) {
  if (hasError) {
    return `${errorId} ${hintId}`;
  }
  return hintId;
}

function messageCountOf(message: string) {
  const length = MESSAGE_COUNT_FORMAT.format(message.length);
  const limit = MESSAGE_COUNT_FORMAT.format(MESSAGE_MAX_LENGTH);
  return `${length} of ${limit} characters`;
}

export function ContactForm() {
  const [values, setValues] = useState(EMPTY_VALUES);
  const [errors, setErrors] = useState<ContactErrors>({});
  const [hasTriedSubmit, setHasTriedSubmit] = useState(false);
  const [status, setStatus] = useState<Status>('editing');
  const nameRef = useRef<HTMLInputElement>(null);
  const emailRef = useRef<HTMLInputElement>(null);
  const teamSizeRef = useRef<HTMLButtonElement>(null);
  const messageRef = useRef<HTMLTextAreaElement>(null);
  const shouldReduceMotion = useReducedMotion();
  const panelVariants = panelVariantsOf(shouldReduceMotion);
  const iconVariants = iconVariantsOf(shouldReduceMotion);
  const labelTransition = labelTransitionOf(shouldReduceMotion);
  const isSending = status === 'sending';
  const isSent = status === 'sent';
  const sendLabel = sendLabelOf(isSending);
  const sendGlyph = sendGlyphOf(isSending);
  const selectedTeamSize = selectedValueOf(values.teamSize);
  const messageCount = messageCountOf(values.message);
  const firstName = firstNameOf(values.name);
  const replyEmail = values.email.trim();
  const messageId = useId();
  const messageHintId = `${messageId}-hint`;
  const messageErrorId = `${messageId}-error`;
  const hasMessageError = Boolean(errors.message);
  const messageDescribedBy = describedByOf(
    messageHintId,
    messageErrorId,
    hasMessageError
  );

  useEffect(() => {
    if (!isSending) {
      return;
    }
    const timeout = window.setTimeout(() => {
      setStatus('sent');
    }, SEND_DELAY_MS);
    return () => window.clearTimeout(timeout);
  }, [isSending]);

  function focusField(field: ContactField) {
    if (field === 'name') {
      nameRef.current?.focus();
    }
    if (field === 'email') {
      emailRef.current?.focus();
    }
    if (field === 'teamSize') {
      teamSizeRef.current?.focus();
    }
    if (field === 'message') {
      messageRef.current?.focus();
    }
  }

  function updateValue(field: ContactField, value: string) {
    const nextValues = { ...values, [field]: value };
    setValues(nextValues);
    if (hasTriedSubmit) {
      const nextErrors = errorsOf(nextValues);
      setErrors(nextErrors);
    }
  }

  function changeText(
    event: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>
  ) {
    const { name, value } = event.target;
    if (isContactField(name)) {
      updateValue(name, value);
    }
  }

  function changeTeamSize(value: string | null) {
    const nextValue = value ?? '';
    updateValue('teamSize', nextValue);
  }

  function submit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const nextErrors = errorsOf(values);
    const firstInvalidField = firstInvalidFieldOf(nextErrors);
    setHasTriedSubmit(true);
    setErrors(nextErrors);
    if (firstInvalidField) {
      focusField(firstInvalidField);
      return;
    }
    setStatus('sending');
  }

  function startOver() {
    setValues(EMPTY_VALUES);
    setErrors({});
    setHasTriedSubmit(false);
    setStatus('editing');
  }

  return (
    <div className='bg-card hairline-ring ring-border dark:bg-foreground/[0.03] rounded-xl p-5 shadow-[0_1px_2px_rgb(0_0_0/0.04)] sm:p-7'>
      <AnimatedSize contentClassName='relative'>
        <AnimatePresence mode='popLayout' initial={false}>
          {isSent && (
            <motion.div
              key='sent'
              role='status'
              variants={panelVariants}
              initial='enter'
              animate='visible'
              exit='exit'
              transition={PANEL_TRANSITION}
              className='flex flex-col items-start gap-4 py-6 sm:py-10'
            >
              <StatusOrb tone='success' />
              <div className='flex flex-col gap-1.5'>
                <p className='text-lg font-semibold'>Message sent</p>
                <p className='text-muted-foreground max-w-md text-[13px] text-pretty'>
                  Thanks, {firstName}. Someone from the team replies to{' '}
                  <span className='text-foreground font-medium break-all'>
                    {replyEmail}
                  </span>{' '}
                  within one working day.
                </p>
              </div>
              <Button variant='outline' onClick={startOver}>
                Send another message
              </Button>
            </motion.div>
          )}
          {!isSent && (
            <motion.form
              key='form'
              noValidate
              onSubmit={submit}
              variants={panelVariants}
              initial='enter'
              animate='visible'
              exit='exit'
              transition={PANEL_TRANSITION}
              className='flex flex-col gap-5'
            >
              <div className='grid gap-5 sm:grid-cols-2'>
                <Field invalid={Boolean(errors.name)}>
                  <FieldLabel>Name</FieldLabel>
                  <Input
                    ref={nameRef}
                    name='name'
                    autoComplete='name'
                    placeholder='Amara Okafor'
                    value={values.name}
                    onChange={changeText}
                    readOnly={isSending}
                  />
                  {errors.name && <FieldError match>{errors.name}</FieldError>}
                </Field>
                <Field invalid={Boolean(errors.email)}>
                  <FieldLabel>Work email</FieldLabel>
                  <Input
                    ref={emailRef}
                    type='email'
                    name='email'
                    autoComplete='email'
                    placeholder='amara@company.com'
                    value={values.email}
                    onChange={changeText}
                    readOnly={isSending}
                  />
                  {errors.email && (
                    <FieldError match>{errors.email}</FieldError>
                  )}
                </Field>
                <Field>
                  <FieldLabel>
                    Company
                    <span className='text-muted-foreground font-normal'>
                      Optional
                    </span>
                  </FieldLabel>
                  <Input
                    name='company'
                    autoComplete='organization'
                    placeholder='Okafor Bakery'
                    value={values.company}
                    onChange={changeText}
                    readOnly={isSending}
                  />
                </Field>
                <Field invalid={Boolean(errors.teamSize)}>
                  <FieldLabel>Team size</FieldLabel>
                  <Select
                    items={TEAM_SIZES}
                    value={selectedTeamSize}
                    onValueChange={changeTeamSize}
                    readOnly={isSending}
                    name='teamSize'
                  >
                    <SelectTrigger ref={teamSizeRef}>
                      <SelectValue placeholder='Pick a size' />
                    </SelectTrigger>
                    <SelectContent>
                      {TEAM_SIZES.map((size) => (
                        <SelectItem key={size.value} value={size.value}>
                          {size.label}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                  {errors.teamSize && (
                    <FieldError match>{errors.teamSize}</FieldError>
                  )}
                </Field>
              </div>
              <Field invalid={hasMessageError}>
                <FieldLabel htmlFor={messageId}>How can we help?</FieldLabel>
                <Textarea
                  ref={messageRef}
                  id={messageId}
                  name='message'
                  rows={4}
                  maxLength={MESSAGE_MAX_LENGTH}
                  placeholder='We answer about 200 emails a week with four people and want to stop replying twice to the same customer.'
                  value={values.message}
                  onChange={changeText}
                  readOnly={isSending}
                  aria-invalid={hasMessageError}
                  aria-describedby={messageDescribedBy}
                  className='min-h-28'
                />
                {hasMessageError && (
                  <FieldError id={messageErrorId} match>
                    {errors.message}
                  </FieldError>
                )}
                <FieldDescription id={messageHintId} className='tabular-nums'>
                  {messageCount}
                </FieldDescription>
              </Field>
              <div className='flex flex-col-reverse gap-3 sm:flex-row sm:items-center sm:justify-between'>
                <p className='text-muted-foreground text-xs'>
                  We only use these details to answer you
                </p>
                <Button
                  type='submit'
                  size='lg'
                  disabled={isSending}
                  focusableWhenDisabled
                  className='data-disabled:opacity-100'
                >
                  <AnimatePresence mode='popLayout' initial={false}>
                    <motion.span
                      key={sendGlyph.key}
                      className='flex'
                      variants={iconVariants}
                      initial='enter'
                      animate='visible'
                      exit='exit'
                      transition={PANEL_TRANSITION}
                    >
                      {sendGlyph.icon}
                    </motion.span>
                  </AnimatePresence>
                  <motion.span layout transition={labelTransition}>
                    {sendLabel}
                  </motion.span>
                </Button>
              </div>
            </motion.form>
          )}
        </AnimatePresence>
      </AnimatedSize>
    </div>
  );
}

export type ContactValues = {
  name: string;
  email: string;
  company: string;
  teamSize: string;
  message: string;
};

export type ContactField = keyof ContactValues;

export type ContactErrors = Partial<Record<ContactField, string>>;

export const MESSAGE_MIN_LENGTH = 20;

export const MESSAGE_MAX_LENGTH = 1000;

export const EMPTY_VALUES: ContactValues = {
  name: '',
  email: '',
  company: '',
  teamSize: '',
  message: '',
};

const FIELD_ORDER: ContactField[] = [
  'name',
  'email',
  'company',
  'teamSize',
  'message',
];

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export function isContactField(value: string): value is ContactField {
  return FIELD_ORDER.some((field) => field === value);
}

function isBlank(value: string) {
  const trimmed = value.trim();
  return trimmed.length === 0;
}

function nameErrorOf(value: string) {
  if (isBlank(value)) {
    return 'Enter your name so we know who to answer';
  }
  return null;
}

function emailErrorOf(value: string) {
  if (isBlank(value)) {
    return 'Enter your work email';
  }
  const trimmed = value.trim();
  const isEmailShaped = EMAIL_PATTERN.test(trimmed);
  if (!isEmailShaped) {
    return 'Check the address, it should look like name@company.com';
  }
  return null;
}

function teamSizeErrorOf(value: string) {
  if (isBlank(value)) {
    return 'Pick the size of your team';
  }
  return null;
}

function messageErrorOf(value: string) {
  const trimmed = value.trim();
  const isTooShort = trimmed.length < MESSAGE_MIN_LENGTH;
  if (isTooShort) {
    return `Tell us a little more, at least ${MESSAGE_MIN_LENGTH} characters`;
  }
  const isTooLong = trimmed.length > MESSAGE_MAX_LENGTH;
  if (isTooLong) {
    return 'Keep the message under 1,000 characters';
  }
  return null;
}

function addError(
  errors: ContactErrors,
  field: ContactField,
  error: string | null
) {
  if (error) {
    errors[field] = error;
  }
}

export function errorsOf(values: ContactValues) {
  const errors: ContactErrors = {};
  const nameError = nameErrorOf(values.name);
  const emailError = emailErrorOf(values.email);
  const teamSizeError = teamSizeErrorOf(values.teamSize);
  const messageError = messageErrorOf(values.message);
  addError(errors, 'name', nameError);
  addError(errors, 'email', emailError);
  addError(errors, 'teamSize', teamSizeError);
  addError(errors, 'message', messageError);
  return errors;
}

export function firstInvalidFieldOf(errors: ContactErrors) {
  const invalidFields = FIELD_ORDER.filter((field) => errors[field]);
  if (invalidFields.length === 0) {
    return null;
  }
  return invalidFields[0];
}

export function firstNameOf(name: string) {
  const trimmed = name.trim();
  const words = trimmed.split(' ');
  return words[0];
}

